input.code:
const ids = {};
const films = [
  ["Puncture", "Q376723"],
  ["Candy", "Q280928"],
  ["Half Nelson", "Q1156078"],
];
for (const [name, qid] of films) {
  try {
    const r = await fetch(`https://www.wikidata.org/wiki/Special:EntityData/${qid}.json`);
    const j = await r.json();
    const e = j.entities[qid];
    const claims = e.claims || {};
    const tmdb = (claims.P4947 || []).map(c => c.mainsnak.datavalue.value);
    const imdb = (claims.P345 || []).map(c => c.mainsnak.datavalue.value);
    ids[name] = {tmdb, imdb};
  } catch (err) { ids[name] = {error: String(err)}; }
}
return ids;

