const out = {};
const queries = [
  ["The Infiltrator 2016 Bryan Cranston film", "The Infiltrator"],
  ["Beauty and the Beast 2014 Christophe Gans", "La Belle et la Bête"],
  ["The Boys from Brazil 1978", "The Boys from Brazil"],
  ["Knight of Cups", "Knight of Cups"],
];
for (const [label, q] of queries) {
  try {
    const url = `https://www.wikidata.org/w/api.php?action=wbsearchentities&search=${encodeURIComponent(q)}&language=en&format=json&limit=10&type=item`;
    const r = await fetch(url);
    const j = await r.json();
    out[label] = (j.search||[]).map(s => ({id: s.id, label: s.label, desc: s.description}));
  } catch (e) { out[label] = String(e); }
}
return out;

